//不知道理解得对不对
//房间组中保存的是不同颜色世界中的当前房间，历史房间通过当前房间的来源房间的来源房间的来源房间...这种链式结构保存。
//当前房间=房间组【当前颜色】

房间组=｛颜色1:房间,颜色2:房间,颜色3:房间,...｝;
当前颜色=颜色1;

房间｛
　属性：｛来源房间，出口，私有物品，公有物品｝
　离开：｛如果存在来源房间｛
　　如果手持物品则将物品移至来源房间；
　　如果来源房间出口不为空，且来源房间目前物品中存在出口，则当前房间指向来源房间；
　　否则当前房间指向悖论；
　｝｝
　输出：｛
　　如果存在来源房间｛
　　　生成指向来源房间的罐子；
　　　将罐子放入来源房间私有物品；
　　　当前房间指向来源房间；
　　｝
　｝
}
宝箱{
　属性：｛房间生成｛
　　返回一个房间实例；
　｝｝
　进入：｛
　　新建一个房间实例；
　　如果有手持物品且物品不为当前宝箱，则将物品放入新房间；
　　当前房间的出口等于当前宝箱；
　　新房间的来源房间等于当前房间；
　　当前房间指向新房间；
　｝
}
罐子｛
　私有：｛房间生成｛
　　返回存档；
　　将存档设为损坏；//通过复制产生的罐子再次访问时得到损坏；
　｝｝
　进入：｛
　　获得房间存档；
　　如果房间存档未损坏{
　　　删除罐子；
　　　如果有手持物品且物品不为当前罐子，将物品放入存档房间;
　　　当前房间的出口等于空；
　　　存档房间的来源房间等于当前房间；
　　｝
　　当前房间指向存档房间；
　｝
｝

药片{
　使用：｛
　　如果目标不为药片，
　　则从房间删除本药片，并添加目标新实例；
　｝
｝
大锅｛
　属性：｛目标颜色｝
　进入：｛//目标房间等于房间组【目标颜色】
　　当前房间的出口等于当前大锅；
　　如果有手持物品且物品不为当前大锅，将物品放入目标房间;
　　如果目标房间出口不为空，且目标房间目前物品中存在出口，当前颜色等于目标颜色；
　　否则当前房间指向失效；
　｝
｝

//JavaScript
class Room{
    constructor(){
        this.prev=null;
        this.active=null;
        this.things=null;
        this.g_things=null;
    }
    out(thing){
        if(this.prev){
            if(thing){
                Room.move(this.prev,thing,this,thing);
            }
            if(this.prev.active===null || this.prev.getType(this.prev.active)){
                contexts[thread]=this.prev;
            }else{
                contexts[thread]=new String("PARADOX_1");
            }
        }
    }
    yield(){
        if(this.prev){
            let jar=new Jar(this);
            this.prev.things.push(jar);
            contexts[thread]=this.prev;
        }
    }
    getType(thing){
        if(this.things.includes(thing))return "things";
        if(this.g_things.includes(thing))return "g_things";
        return false;
    }
    static move(room_in,thing_in,room_out,thing_out){
        let type=room_out.getType(thing_out);
        if(type){
            room_out[type].splice(room_out[type].findIndex(o=>o==thing_out),1);
            room_in[type].push(thing_in);
        }
    }
}
class Chest{
    constructor(room){
        this.room=room;
    }
    in(thing){
        let target=this.room();
        if(thing && thing!=this){
            Room.move(target,thing,contexts[thread],thing);
        }
        target.prev=contexts[thread];
        target.prev.active=this;
        contexts[thread]=target;
    }
}
class Jar{
    constructor(ctx){
        this.room=function(){
            let tmp=ctx;
            if(tmp instanceof Room){
                ctx=new String("BUG");
            }
            return tmp;
        }
    }
    in(thing){
        let target=this.room();
        if(target instanceof Room){
            let type=contexts[thread].getType(this);
            if(type){
                contexts[thread][type].splice(contexts[thread][type].findIndex(o=>o==this),1);
            }
            if(thing && thing!=this){
                Room.move(target,thing,contexts[thread],thing);
            }
            target.prev=contexts[thread];
            target.prev.active=null;
        }
        contexts[thread]=target;
    }
}
class Generic{
    use(thing){
        if(thing instanceof Generic)return;
        let tmp=Object.assign(Object.create(Object.getPrototypeOf(thing)),thing);
        Room.move(contexts[thread],tmp,contexts[thread],this);
    }
}
class Cauldron{
    constructor(thread){this.thread=thread;}
    in(thing){
        contexts[thread].active=this;
        let target = contexts[this.thread];
        if(thing && thing!=this){
            Room.move(target,thing,contexts[thread],thing);
        }
        if(target.active && target.getType(target.active)){
            thread=this.thread;
        }else{
            contexts[thread]=new String("PARADOX_2");
        }
    }
}

let roomFac=function(t,g){
    let g_things=g;
    return function(){
        let things=t.map(
            thing=>Object.assign(Object.create(Object.getPrototypeOf(thing)),thing)
        );
        let r=new Room();
        r.g_things=g_things;
        r.things=things;
        return r;
    }
}
let room1,chest1=new Chest(),chest2=new Chest(),generic1=new Generic(),cauldron1=new Cauldron(1);
room1=roomFac([chest1,cauldron1],[chest2,generic1]);
chest1.room=room1;
chest2.room=room1;

let contexts=[room1(),room1(),room1()];
let thread=0;
